package vn.covie.checkout.application; import java.util.*; import org.springframework.stereotype.Component; import vn.covie.cart.model.*; import vn.covie.cart.persistence.*; import vn.covie.catalog.model.*; import vn.covie.catalog.persistence.*; import vn.covie.checkout.api.dto.CheckoutPreviewRequest; import vn.covie.checkout.model.CheckoutSourceType; import vn.covie.merchants.persistence.*; import vn.covie.shared.web.*; import org.springframework.http.HttpStatus;
@Component public class CartCheckoutCandidateResolver implements CheckoutCandidateResolver{private final CartRepository carts;private final CartItemRepository items;private final LocationVariantRepository offers;private final VariantRepository variants;private final CatalogItemRepository catalog;private final MerchantLocationRepository locations;public CartCheckoutCandidateResolver(CartRepository carts,CartItemRepository items,LocationVariantRepository offers,VariantRepository variants,CatalogItemRepository catalog,MerchantLocationRepository locations){this.carts=carts;this.items=items;this.offers=offers;this.variants=variants;this.catalog=catalog;this.locations=locations;}public CheckoutSourceType supports(){return CheckoutSourceType.CART;}public CheckoutCandidate resolve(UUID user,CheckoutPreviewRequest request){if(request.cartId()==null||request.items()!=null&&!request.items().isEmpty())throw invalid("CART checkout does not accept items.");CartEntity cart=carts.findById(request.cartId()).filter(c->c.getUserId().equals(user)&&c.getCartStatus()==CartStatus.ACTIVE).orElseThrow(CartCheckoutCandidateResolver::notFound);List<CartItemEntity> lines=items.findByCartIdOrderByAddedAtAsc(cart.getId());if(lines.isEmpty())throw invalid("Cart is empty.");List<CheckoutCandidateItem> result=new ArrayList<>();CatalogItemType type=null;UUID merchant=null;for(var line:lines){var offer=offers.findByIdAndDeletedAtIsNull(line.getLocationVariantId()).orElseThrow(CartCheckoutCandidateResolver::notFound);var variant=variants.findById(offer.getVariantId()).orElseThrow(CartCheckoutCandidateResolver::notFound);var item=catalog.findById(variant.getCatalogItemId()).orElseThrow(CartCheckoutCandidateResolver::notFound);if(type==null)type=item.getItemType();if(type!=item.getItemType())throw invalid("Cart cannot mix item types.");if(merchant==null)merchant=item.getMerchantProfileId();result.add(new CheckoutCandidateItem(offer.getId(),variant.getId(),item.getId(),line.getQuantity()));}var loc=locations.findById(cart.getMerchantLocationId()).orElseThrow(CartCheckoutCandidateResolver::notFound);return new CheckoutCandidate(CheckoutSourceType.CART,user,merchant,loc.getId(),type,List.copyOf(result),cart.getVersion(),null);}private static ApiException invalid(String m){return new ApiException(ErrorCode.CHECKOUT_SOURCE_INVALID,HttpStatus.UNPROCESSABLE_ENTITY,m);}private static ApiException notFound(){return new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Resource not found.");}}
